from modele import *

notes=tableau(['Note','$6$','$8$','$10$','$12$','$16$'],[['Effectif','$2$','$3$','$6$','$5$','$4$']])
chapitre(10,'statistiques','Statistiques et boîtes à moustaches','3 · Données et probabilités',
'Effectifs cumulés · Médiane · Quartiles · Boîtes à moustaches · Tableur',
['Calculer et interpréter moyenne, médiane, quartiles et étendue.','Utiliser les effectifs cumulés croissants.','Construire et comparer des boîtes à moustaches.'],['Moyenne, médiane, étendue et fréquences.'],[
r'''\essSection{1}{Effectifs cumulés, médiane et quartiles}
\begin{definition}L’effectif cumulé croissant d’une valeur est le nombre d’observations inférieures ou égales à cette valeur. Le dernier effectif cumulé est l’effectif total $N$. La moyenne est la somme des valeurs, chacune comptée avec son effectif, divisée par $N$.\end{definition}
\begin{definition}Une médiane partage la série ordonnée en deux groupes de même effectif. Si $N$ est impair, c’est la valeur de rang $(N+1)/2$ ; si $N$ est pair, ce livre retient la moyenne des valeurs de rangs $N/2$ et $N/2+1$.\end{definition}
\begin{definition}Le premier quartile $Q_1$ est la plus petite valeur de la série telle qu’au moins 25\,\% des valeurs lui soient inférieures ou égales. Le troisième quartile $Q_3$ est la plus petite valeur telle qu’au moins 75\,\% des valeurs lui soient inférieures ou égales.\end{definition}
\begin{exemple}Pour $N=20$, $Q_1$ est la 5\textsuperscript{e} valeur, car $20\times0{,}25=5$, et $Q_3$ la 15\textsuperscript{e}, car $20\times0{,}75=15$. Pour $N=11$, $11\times0{,}25=2{,}75$ : $Q_1$ est la 3\textsuperscript{e} valeur. On arrondit le rang à l’entier supérieur.\end{exemple}
\begin{savoirfaire}[Lire les rangs]Ranger les valeurs ou calculer les effectifs cumulés croissants ; repérer la première valeur dont l’effectif cumulé atteint le rang cherché.\end{savoirfaire}''',
r'''\essSection{2}{Boîtes à moustaches et comparaisons}
\begin{definition}Une boîte à moustaches représente, sur un axe gradué, le minimum, $Q_1$, la médiane, $Q_3$ et le maximum. La boîte va de $Q_1$ à $Q_3$ et contient environ la moitié centrale des valeurs ; les moustaches rejoignent les extrêmes.\end{definition}
\begin{savoirfaire}[Comparer deux séries]Comparer les médianes pour la position, puis l’étendue et la longueur $Q_3-Q_1$ de la boîte pour la dispersion. Une phrase précise s’appuie sur un pourcentage : « au moins 75\,\% des valeurs sont inférieures ou égales à $Q_3$ ».\end{savoirfaire}
\begin{savoirfaire}[Tableur]Les fonctions MOYENNE, MEDIANE, MIN et MAX calculent ces indicateurs sur une plage de cellules, par exemple \code{=MAX(A2:A21)-MIN(A2:A21)} pour l’étendue. La fonction QUARTILE d’un tableur suit souvent une autre définition et peut donner un résultat différent.\end{savoirfaire}
\begin{attention}Une moyenne identique n’impose ni une médiane identique ni une même dispersion. Une valeur extrême peut déplacer fortement la moyenne sans changer la médiane. Lire l’origine des axes avant de comparer des hauteurs.\end{attention}'''],[
E('Trois indicateurs',r"Pour la série $7\,;9\,;10\,;14\,;15$, calculer la moyenne, la médiane et l’étendue.",r"La somme vaut 55 : la moyenne vaut $55/5=\res{11}$. La valeur centrale, de rang 3, donne la médiane $\res{10}$. L’étendue vaut $15-7=\res8$. Moyenne et médiane répondent à des questions différentes.","Additionner, repérer le rang central, puis soustraire les extrêmes.","assert sum([7,9,10,14,15])/5==11 and sorted([7,9,10,14,15])[2]==10 and 15-7==8"),
E('Une fréquence',r"Dans un groupe de 30 élèves, 12 viennent à vélo. Donner la fréquence et le pourcentage correspondants.",r"La fréquence est $12/30=\res{0{,}4}$, soit $\res{40\,\%}$. Le dénominateur est l’effectif de tout le groupe.","Identifier le total de référence.","assert Rational(12,30)==Rational('.4')"),
E('Des effectifs cumulés',r"Calculer les effectifs cumulés croissants de la série de notes, puis l’effectif total."+notes,r"On additionne les effectifs de proche en proche : $\res{2\,;5\,;11\,;16\,;20}$. L’effectif total est le dernier effectif cumulé, $\res{20}$. Par exemple, 11 élèves ont une note inférieure ou égale à 10.","Ajouter chaque effectif au cumul précédent.","from itertools import accumulate\nassert list(accumulate([2,3,6,5,4]))==[2,5,11,16,20]"),
E('Ordonner avant la médiane',r"Déterminer la médiane de $13\,;4\,;9\,;7\,;11$, puis celle de $1\,;3\,;6\,;8\,;10\,;20$.",r"La première liste ordonnée est $4\,;7\,;9\,;11\,;13$ : la médiane est la 3\textsuperscript{e} valeur, $\res9$. La seconde a six valeurs : on retient $(6+8)/2=\res7$. La valeur 20 n’influence pas cette médiane.","Ranger avant de choisir le rang central.","assert sorted([13,4,9,7,11])[2]==9 and Rational(6+8,2)==7"),
E('Lire une boîte à moustaches',r"La boîte à moustaches résume les durées, en minutes, d’un trajet. Lire le minimum, les quartiles, la médiane et le maximum. Calculer l’étendue et compléter : « au moins … \% des durées sont inférieures ou égales à 14 min ».",r"On lit $\res{4\,;8\,;11\,;14\,;19}$ pour le minimum, $Q_1$, la médiane, $Q_3$ et le maximum. L’étendue vaut $19-4=\res{15\text{ min}}$. Comme $Q_3=14$, au moins $\res{75\,\%}$ des durées sont inférieures ou égales à 14 min.","Associer chaque trait de la boîte à un indicateur.","assert 19-4==15",figure='boite-lecture'),
E('Moyenne et quartiles d’un tableau',r"Pour la série de notes de l’exercice 3, calculer la moyenne, la médiane et les deux quartiles."+notes,r"La somme pondérée vaut $12+24+60+60+64=220$ : moyenne $\res{11}$. Avec $N=20$, les rangs 10 et 11 portent 10 : médiane $\res{10}$. $Q_1$ est la 5\textsuperscript{e} valeur, d’effectif cumulé atteint à 8 : $\res{Q_1=8}$. $Q_3$ est la 15\textsuperscript{e}, atteinte à 12 : $\res{Q_3=12}$.","Utiliser les effectifs cumulés pour trouver les rangs.","v=[6]*2+[8]*3+[10]*6+[12]*5+[16]*4; assert sum(v)==220 and v[9]==v[10]==10 and v[4]==8 and v[14]==12"),
E('Quartiles d’une série brute',r"Déterminer la médiane et les quartiles de la série ordonnée $3\,;5\,;6\,;8\,;9\,;10\,;12\,;13\,;15\,;18\,;20$.",r"$N=11$. La médiane est la 6\textsuperscript{e} valeur : $\res{10}$. $11\times0{,}25=2{,}75$, donc $Q_1$ est la 3\textsuperscript{e} valeur : $\res6$. $11\times0{,}75=8{,}25$, donc $Q_3$ est la 9\textsuperscript{e} valeur : $\res{15}$.","Calculer les rangs, arrondis à l’entier supérieur.","v=[3,5,6,8,9,10,12,13,15,18,20]; assert v[5]==10 and v[ceil(11*Rational(1,4))-1]==6 and v[ceil(11*Rational(3,4))-1]==15"),
E('Construire une boîte',r"Construire la boîte à moustaches de la série de l’exercice précédent sur l’axe gradué fourni.",r"On place le minimum 3, $Q_1=6$, la médiane 10, $Q_3=15$ et le maximum 20. La boîte va de 6 à 15, avec un trait à 10 ; les moustaches vont de 3 à 6 et de 15 à 20. Le corrigé la montre en vert, avec l’échelle de l’axe.","Placer les cinq valeurs avant de dessiner la boîte.","assert [3,6,10,15,20]==sorted([3,6,10,15,20])",figure='boite-construire'),
E('Quartiles et diagramme en barres',r"Le diagramme en barres donne le nombre de livres lus pendant les vacances par les élèves d’une classe. Déterminer l’effectif total, la médiane et les quartiles.",r"Les effectifs 3, 7, 9, 6, 5 donnent les cumuls 3, 10, 19, 25, 30 : $\res{N=30}$. Les rangs 15 et 16 valent 3 livres : médiane $\res3$. $30\times0{,}25=7{,}5$ : rang 8, $\res{Q_1=2}$. $30\times0{,}75=22{,}5$ : rang 23, $\res{Q_3=4}$.","Passer des hauteurs aux effectifs cumulés.","v=[1]*3+[2]*7+[3]*9+[4]*6+[5]*5; assert len(v)==30 and v[14]==v[15]==3 and v[7]==2 and v[22]==4",figure='stat-barres'),
E('Des formules de tableur',r"Les durées 12, 15, 9, 20, 15, 11, 18 et 14, en minutes, sont saisies dans les cellules A2 à A9. Écrire des formules donnant la moyenne, la médiane et l’étendue, puis donner les résultats.",r"On peut saisir \code{=MOYENNE(A2:A9)}, \code{=MEDIANE(A2:A9)} et \code{=MAX(A2:A9)-MIN(A2:A9)}. La moyenne vaut $114/8=\res{14{,}25}$. La série ordonnée est 9, 11, 12, 14, 15, 15, 18, 20 : médiane $(14+15)/2=\res{14{,}5}$. L’étendue vaut $\res{11}$.","Désigner une plage de cellules, puis contrôler à la main.","v=[12,15,9,20,15,11,18,14]; w=sorted(v); assert Rational(sum(v),8)==Rational('14.25') and Rational(w[3]+w[4],2)==Rational('14.5') and max(v)-min(v)==11"),
E('Réunir deux groupes',r"Un groupe de 12 élèves a une moyenne de 13 ; un autre de 18 élèves a une moyenne de 11. Quelle est la moyenne des 30 élèves ?",r"Les sommes valent $12\times13=156$ et $18\times11=198$. La moyenne commune vaut $(156+198)/30=\res{11{,}8}$. Faire $(13+11)/2$ donnerait un poids égal à des groupes de tailles différentes.","Reconstituer les sommes de chaque groupe.","assert Rational(12*13+18*11,30)==Rational('11.8')"),
E('Comparer deux collèges',r"Les boîtes à moustaches résument les durées de trajet, en minutes, des élèves de deux collèges A et B. Comparer les médianes et les dispersions. Dans quel collège au moins un quart des élèves mettent-ils 22 minutes ou plus ?",r"Les médianes sont 15 min pour A et 14 min pour B : positions proches. A est plus dispersé : étendue $40-5=35$ contre $25-8=17$, boîte de longueur $22-10=12$ contre $17-12=5$. Dans $\res{A}$, $Q_3=22$ : moins de 75 \% des durées sont inférieures à 22 min, donc au moins 25 \% des élèves mettent 22 min ou plus. Dans B, $Q_3=17$ : on sait seulement qu’au plus un quart des élèves mettent plus de 17 min, on ne peut pas l’affirmer.","Comparer d’abord les médianes, puis les longueurs des boîtes et les étendues.","assert 40-5==35 and 25-8==17 and 22-10==12 and 17-12==5",figure='boites-comparer'),
E('Ajouter une observation',r"Une série de 9 valeurs a une moyenne de 14. On ajoute 24. Calculer la nouvelle moyenne. Peut-on en déduire la nouvelle médiane ?",r"L’ancienne somme est 126 ; la nouvelle vaut 150 pour 10 valeurs. La moyenne est $\res{15}$. La médiane reste inconnue : la somme ne renseigne pas sur les valeurs centrales. Par exemple neuf fois 14, ou huit fois 13 et une fois 22, ont la même moyenne initiale mais des médianes différentes après l’ajout.","Séparer ce que détermine la somme de ce qui demande l’ordre.","assert (9*14+24)/10==15 and 8*13+22==126 and Rational(14+14,2)!=Rational(13+13,2)"),
E('Même moyenne, mêmes résultats ?',r"Comparer les séries A : $9\,;10\,;10\,;11$ et B : $2\,;10\,;10\,;18$. Calculer moyenne, médiane et étendue, puis commenter.",r"Les deux sommes valent 40 : les moyennes sont 10. Les deux médianes sont 10. Les étendues sont $\res2$ et $\res{16}$. B est beaucoup plus dispersée ; les seuls indicateurs de position masquent cet écart.","Comparer un indicateur de position et un de dispersion.","assert sum([9,10,10,11])==sum([2,10,10,18])==40 and 11-9==2 and 18-2==16"),
E('Un graphique trompeur',r"Deux barres représentent 80 et 84 inscriptions. Un axe vertical commence à 78. Comparer la hausse réelle et les hauteurs visibles à partir de 78.",r"La hausse réelle est $(84-80)/80=\res{5\,\%}$. Les hauteurs visibles sont 2 et 6, dans un rapport 3. Ce rapport visuel ne traduit pas un triplement des inscriptions. Lire l’origine et les graduations avant de comparer.","Ramener le pourcentage à la valeur initiale.","assert Rational(84-80,80)==Rational(5,100) and Rational(84-78,80-78)==3",figure='stat-axe-tronque')
],reperes=['Moyenne, médiane et étendue','Effectifs cumulés et quartiles','Boîtes à moustaches','Comparer et interpréter des séries'])

chapitre(11,'probabilites','Probabilités, évènements et simulations','3 · Données et probabilités',
'Issues · Évènements · Réunion · Intersection · Tableaux · Fréquences',
['Décrire des évènements avec le vocabulaire des ensembles.',r'Utiliser la relation $P(A\cup B)+P(A\cap B)=P(A)+P(B)$.','Dénombrer les issues de deux épreuves indépendantes et interpréter une simulation.'],['Fractions, probabilité d’un évènement et de son contraire.'],[
r'''\essSection{1}{Évènements et opérations}
\begin{definition}Une issue est un résultat possible d’une expérience aléatoire. Un évènement est un ensemble d’issues. L’évènement contraire de $A$, noté $\overline A$, contient les issues qui ne réalisent pas $A$. L’évènement impossible correspond à l’ensemble vide $\varnothing$.\end{definition}
\begin{definition}L’intersection $A\cap B$ (« $A$ et $B$ ») contient les issues communes à $A$ et $B$. La réunion $A\cup B$ (« $A$ ou $B$ ») contient les issues de $A$, de $B$, ou des deux. $A$ et $B$ sont incompatibles si $A\cap B=\varnothing$.\end{definition}
\begin{propriete}Si les issues sont équiprobables, $P(A)$ est le nombre d’issues favorables divisé par le nombre total d’issues. De plus $P(\overline A)=1-P(A)$ et
\[P(A\cup B)+P(A\cap B)=P(A)+P(B).\]\end{propriete}
\begin{exemple}Avec un dé équilibré, $A$ : « pair » $=\{2;4;6\}$ et $B$ : « au moins 4 » $=\{4;5;6\}$. $A\cap B=\{4;6\}$ et $A\cup B=\{2;4;5;6\}$ : on vérifie $4/6+2/6=3/6+3/6$.\end{exemple}
\begin{attention}Le « ou » des mathématiques est inclusif. « $A$ ou $B$, mais pas les deux » se dit « ou exclusif » ; sa probabilité vaut $P(A\cup B)-P(A\cap B)$.\end{attention}''',
r'''\essSection{2}{Deux épreuves et simulations}
\begin{savoirfaire}[Dénombrer]Pour deux épreuves indépendantes, un tableau à double entrée ou un arbre de dénombrement liste toutes les issues. Si chaque épreuve a des issues équiprobables, les couples obtenus le sont aussi : deux dés donnent $6\times6=36$ couples équiprobables.\end{savoirfaire}
\begin{exemple}Deux pièces équilibrées lancées indépendamment donnent quatre issues équiprobables : PP, PF, FP, FF. L’évènement « exactement une face F » contient PF et FP, donc a pour probabilité $2/4=1/2$.\end{exemple}
\begin{savoirfaire}[Numéroter pour compter]Dans un sac de 3 boules rouges et 2 bleues, numéroter les boules $R_1,R_2,R_3,B_1,B_2$. Avec remise, deux tirages donnent $5\times5=25$ couples équiprobables, dont $3\times3=9$ formés de deux rouges.\end{savoirfaire}
\begin{propriete}Simuler une expérience, c’est la reproduire par un dispositif ou un programme qui respecte le modèle, par exemple un nombre entier aléatoire de 1 à 6 pour un dé. Quand le nombre de répétitions augmente, la fréquence observée se stabilise généralement autour de la probabilité. Cela ne prédit ni le prochain résultat ni une égalité exacte.\end{propriete}'''],[
E('Un dé',r"On lance un dé équilibré à six faces numérotées de 1 à 6. Quelle est la probabilité d’obtenir un nombre pair ?",r"Les issues favorables sont 2, 4 et 6, parmi six issues équiprobables. La probabilité vaut $3/6=\res{1/2}$.","Énumérer les issues favorables.","assert Rational(len([a for a in range(1,7) if a%2==0]),6)==Rational(1,2)"),
E('Des boules colorées',r"Un sac contient 5 boules rouges, 3 bleues et 2 vertes, indiscernables au toucher. On tire une boule au hasard. Donner les probabilités de rouge et de non-rouge.",r"Le total vaut 10. $P(R)=5/10=\res{1/2}$ et $P(\overline R)=1-1/2=\res{1/2}$. Trois couleurs ne signifient pas trois issues équiprobables.","Compter les boules plutôt que les couleurs.","assert Rational(5,10)==1-Rational(5,10)==Rational(1,2)"),
E('Écrire des évènements',r"On lance un dé équilibré. $A$ est l’évènement « obtenir un nombre pair » et $B$ l’évènement « obtenir un multiple de 3 ». Écrire $A$, $B$, $A\cap B$, $A\cup B$ et $\overline A$ sous forme d’ensembles.",r"$A=\{2;4;6\}$, $B=\{3;6\}$. $\res{A\cap B=\{6\}}$, $\res{A\cup B=\{2;3;4;6\}}$ et $\res{\overline A=\{1;3;5\}}$. L’issue 6 n’est comptée qu’une fois dans la réunion.","Lister les issues de chaque évènement avant de les combiner.","A={2,4,6};B={3,6}; assert A&B=={6} and A|B=={2,3,4,6} and set(range(1,7))-A=={1,3,5}"),
E('Impossible ou certain',r"Sur un dé classique, donner les probabilités d’obtenir 9 et d’obtenir moins de 7. Comment note-t-on l’évènement impossible ?",r"Obtenir 9 est impossible : probabilité $\res0$ ; cet évènement est l’ensemble vide $\varnothing$. Toutes les faces sont inférieures à 7 : l’évènement est certain, de probabilité $\res1$.","Comparer l’évènement à toutes les issues.","assert all(a<7 for a in range(1,7)) and 9 not in range(1,7)"),
E('Une fréquence expérimentale',r"On obtient 46 fois face au cours de 100 lancers d’une pièce. Donner la fréquence de face. Est-ce une preuve que la pièce est déséquilibrée ?",r"La fréquence est $46/100=\res{0{,}46}$. Cet écart à 0,5 peut se produire avec une pièce équilibrée ; ce seul résultat n’est pas une preuve. La fréquence dépend de l’expérience réalisée.","Ne pas confondre résultat observé et modèle.","assert Rational(46,100)==Rational('.46')"),
E('La relation de la réunion',r"Avec les évènements de l’exercice 3, calculer $P(A)$, $P(B)$ et $P(A\cap B)$, puis en déduire $P(A\cup B)$ par la relation du cours. Contrôler par un dénombrement.",r"$P(A)=3/6=1/2$, $P(B)=2/6=1/3$ et $P(A\cap B)=1/6$. La relation donne $P(A\cup B)=1/2+1/3-1/6=\res{2/3}$. Contrôle : $A\cup B$ contient 4 issues sur 6, et $4/6=2/3$.",r"Isoler $P(A\cup B)$ dans la relation.","assert Rational(1,2)+Rational(1,3)-Rational(1,6)==Rational(2,3)==Rational(4,6)"),
E('Deux pièces',r"Deux pièces équilibrées sont lancées indépendamment. Compléter l’arbre de dénombrement et calculer la probabilité d’obtenir exactement une face F, puis au moins une face F.",r"Les quatre issues équiprobables sont PP, PF, FP, FF. Exactement une face : PF et FP, d’où $\res{1/2}$. Au moins une face : PF, FP, FF, d’où $\res{3/4}$, ou $1-1/4$ par le contraire PP.","Suivre toutes les branches de l’arbre.","assert Rational(2,4)==Rational(1,2) and 1-Rational(1,4)==Rational(3,4)",figure='proba-pieces'),
E('La somme de deux dés',r"Deux dés équilibrés sont lancés indépendamment. Utiliser le tableau des sommes pour calculer la probabilité d’une somme égale à 7.",r"Les 36 couples ordonnés sont équiprobables. Les six couples $(1;6),(2;5),(3;4),(4;3),(5;2),(6;1)$ conviennent : $\res{1/6}$. Les sommes elles-mêmes ne sont pas équiprobables.","Compter des couples et non des sommes.","assert sum(a+b==7 for a in range(1,7) for b in range(1,7))==6",figure='proba-des'),
E('Un « ou » exclusif',r"On lance un dé équilibré. $A$ : « pair » et $B$ : « au moins 4 ». Calculer la probabilité de l’évènement « $A$ ou $B$, mais pas les deux ».",r"$A\cup B=\{2;4;5;6\}$ et $A\cap B=\{4;6\}$. Les issues cherchées sont 2 et 5 : probabilité $2/6=\res{1/3}$. Par le calcul : $P(A\cup B)-P(A\cap B)=4/6-2/6$.","Retirer de la réunion les issues communes.","A={2,4,6};B={4,5,6}; assert (A|B)-(A&B)=={2,5} and Rational(len((A|B)-(A&B)),6)==Rational(1,3)"),
E('Au moins un six',r"Deux dés équilibrés sont lancés. On note $A$ : « le premier dé donne 6 » et $B$ : « le second dé donne 6 ». Calculer la probabilité d’obtenir au moins un six.",r"« Au moins un six » est $A\cup B$. $P(A)=P(B)=6/36$ et $A\cap B$ ne contient que $(6;6)$. Donc $P(A\cup B)=6/36+6/36-1/36=\res{11/36}$. Additionner $1/6+1/6$ aurait compté deux fois le couple $(6;6)$.","Utiliser la relation de la réunion pour éviter un double comptage.","assert sum(a==6 or b==6 for a in range(1,7) for b in range(1,7))==11 and Rational(6,36)*2-Rational(1,36)==Rational(11,36)",figure='proba-des'),
E('Deux tirages avec remise',r"Un sac contient 3 boules rouges $R_1,R_2,R_3$ et 2 bleues $B_1,B_2$. On tire une boule, on la remet, puis on en tire une seconde. Utiliser le tableau pour calculer la probabilité de deux rouges, puis de deux boules de même couleur.",r"Le tableau compte $5\times5=25$ couples équiprobables. Deux rouges : $3\times3=9$ couples, d’où $\res{9/25}$. Deux bleues : 4 couples. Même couleur : $9+4=13$ couples, d’où $\res{13/25}$, car les deux évènements sont incompatibles.","Numéroter les boules pour obtenir des issues équiprobables.","assert sum(a[0]==b[0]=='R' for a in ['R1','R2','R3','B1','B2'] for b in ['R1','R2','R3','B1','B2'])==9 and sum(a[0]==b[0] for a in ['R1','R2','R3','B1','B2'] for b in ['R1','R2','R3','B1','B2'])==13",figure='proba-tableau-boules'),
E('Un jeu à points',r"On paie 2 points pour lancer un dé équilibré. Le 6 rapporte 8 points, le 5 rapporte 4 points, les autres 0. Sur un grand nombre de parties, le gain brut moyen théorique est la somme des gains multipliés par leurs probabilités. Le jeu équilibre-t-il mise et gain moyen ?",r"Le gain brut moyen vaut $8/6+4/6=\res2$ points. Il égale la mise : le bilan net moyen théorique est 0. Cela ne garantit ni un remboursement ni un gain à chaque partie ; un résultat individuel peut être $-2$, 2 ou 6 points nets.","Distinguer gain brut, mise et bilan net.","assert Rational(8,6)+Rational(4,6)==2"),
E('Un effectif inconnu',r"Un sac contient 6 rouges et $b$ bleues seulement. La probabilité de tirer rouge au hasard est $2/5$. Trouver $b$.",r"On écrit $6/(6+b)=2/5$. Les produits en croix donnent $30=12+2b$, donc $\res{b=9}$. Avec 15 boules, $6/15=2/5$, ce qui confirme le résultat.","Traduire le total avant le produit en croix.","assert solve(30-2*(6+x),x)==[9]"),
E('Un code à deux chiffres',r"Un générateur choisit indépendamment et au hasard deux chiffres parmi 0, 1, 2, 3, avec répétition possible. Quelle est la probabilité que ses deux chiffres soient distincts ? Que leur somme soit paire ou que le premier chiffre soit 0 ?",r"Il y a $4\times4=16$ codes équiprobables, dont $4\times3=12$ à chiffres distincts : $\res{3/4}$. Ensuite $P(\text{pair})=8/16$, $P(\text{début }0)=4/16$ et l’intersection contient 00 et 02 : $P=8/16+4/16-2/16=\res{5/8}$.","Préciser si la répétition est autorisée, puis utiliser la relation de la réunion.","assert sum(a!=b for a in range(4) for b in range(4))==12 and sum((a+b)%2==0 or a==0 for a in range(4) for b in range(4))==10"),
E('Estimer sans promettre',r"Un programme simule un évènement de probabilité $1/3$ à l’aide de nombres aléatoires. Il obtient 327 succès en 1000 essais, puis 3354 en 10000 essais. Comparer les écarts entre fréquences et probabilité. Peut-on garantir que tout essai supplémentaire rapproche la fréquence de $1/3$ ?",r"Les fréquences sont 0,327 et 0,3354. Leurs écarts à $1/3$ valent environ 0,00633 et 0,00207. La deuxième est plus proche, ce qui illustre la stabilisation des fréquences. Aucune amélioration à chaque étape n’est garantie : un prochain succès ou échec peut augmenter l’écart.","Comparer les écarts absolus sans en faire une règle monotone.","assert abs(Rational(327,1000)-Rational(1,3))>abs(Rational(3354,10000)-Rational(1,3))")
],reperes=['Évènements, contraire et notations','Réunion, intersection et « ou » exclusif','Dénombrer deux épreuves indépendantes','Fréquences et simulations'],deco='probabilites')
